const Storage={keys:{ACL_RULE:'redis-acl-builder-rule',REDIS_VERSION:'redis-acl-builder-version',LAST_GENERATED_RULE:'redis-acl-builder-last-generated',ACL_RULE_HISTORY:'redis-acl-builder-rule-history',ACL_RULE_HISTORY_POSITION:'redis-acl-builder-rule-history-position'},isAvailable(){try{const test='__storage_test__';localStorage.setItem(test,test);localStorage.removeItem(test);return true;}catch(e){return false;}},save(key,value){if(!this.isAvailable())return;try{localStorage.setItem(key,value);}catch(e){console.warn('Failed to save to localStorage:',e);}},load(key,defaultValue=''){if(!this.isAvailable())return defaultValue;try{const value=localStorage.getItem(key);return value!==null?value:defaultValue;}catch(e){console.warn('Failed to load from localStorage:',e);return defaultValue;}},remove(key){if(!this.isAvailable())return;try{localStorage.removeItem(key);}catch(e){console.warn('Failed to remove from localStorage:',e);}},clearAll(){if(!this.isAvailable())return;try{Object.values(this.keys).forEach(key=>{localStorage.removeItem(key);});}catch(e){console.warn('Failed to clear localStorage:',e);}},cleanupDeprecatedKeys(){if(!this.isAvailable())return;try{localStorage.removeItem('redis-acl-builder-command-test');localStorage.removeItem('redis-acl-builder-keyspace-test');}catch(e){console.warn('Failed to cleanup deprecated keys:',e);}},saveAclRule(rule){this.save(this.keys.ACL_RULE,rule);},loadAclRule(){return this.load(this.keys.ACL_RULE);},saveRedisVersion(version){this.save(this.keys.REDIS_VERSION,version);},loadRedisVersion(){return this.load(this.keys.REDIS_VERSION,'redis7');},saveLastGeneratedRule(rule){this.save(this.keys.LAST_GENERATED_RULE,rule);},loadLastGeneratedRule(){return this.load(this.keys.LAST_GENERATED_RULE);},addToHistory(newRule){try{const historyJson=this.load(this.keys.ACL_RULE_HISTORY,'[]');const history=JSON.parse(historyJson);const position=parseInt(this.load(this.keys.ACL_RULE_HISTORY_POSITION,'-1'));if(history.length===0){const currentCommitted=this.loadAclRule()||'';if(currentCommitted!==newRule){history.push(currentCommitted);}}
if(position>=0&&position<history.length-1){history.splice(position+1);}
if(history.length>0&&history[history.length-1]===newRule){return;}
history.push(newRule);const newPosition=history.length-1;if(history.length>20){history.shift();const adjustedPosition=Math.max(0,newPosition-1);this.save(this.keys.ACL_RULE_HISTORY_POSITION,adjustedPosition.toString());}else{this.save(this.keys.ACL_RULE_HISTORY_POSITION,newPosition.toString());}
this.save(this.keys.ACL_RULE_HISTORY,JSON.stringify(history));}catch(e){console.warn('Failed to add rule to history:',e);}},undoFromHistory(){try{const historyJson=this.load(this.keys.ACL_RULE_HISTORY,'[]');const history=JSON.parse(historyJson);const position=parseInt(this.load(this.keys.ACL_RULE_HISTORY_POSITION,'-1'));if(history.length===0){return{error:'no_history'};}
if(position<=0){return{error:'at_beginning'};}
const newPosition=position-1;this.save(this.keys.ACL_RULE_HISTORY_POSITION,newPosition.toString());return{rule:history[newPosition]};}catch(e){console.warn('Failed to undo from history:',e);return{error:'system_error'};}},redoFromHistory(){try{const historyJson=this.load(this.keys.ACL_RULE_HISTORY,'[]');const history=JSON.parse(historyJson);const position=parseInt(this.load(this.keys.ACL_RULE_HISTORY_POSITION,'-1'));if(history.length===0){return{error:'no_history'};}
if(position>=history.length-1){return{error:'at_end'};}
const newPosition=position+1;this.save(this.keys.ACL_RULE_HISTORY_POSITION,newPosition.toString());return{rule:history[newPosition]};}catch(e){console.warn('Failed to redo from history:',e);return{error:'system_error'};}},hasHistory(){try{const historyJson=this.load(this.keys.ACL_RULE_HISTORY,'[]');const history=JSON.parse(historyJson);return history.length>0;}catch(e){return false;}},clearHistory(){this.save(this.keys.ACL_RULE_HISTORY,'[]');this.save(this.keys.ACL_RULE_HISTORY_POSITION,'-1');}};export default Storage;